'use client';import{useEffect,useMemo,useState}from'react';import{geoAlbersUsa,geoPath}from'd3-geo';import{feature,mesh}from'topojson-client';import{usTopologyBase64}from'./us-map';import{parks,figures,mapStates}from'./data';
type L='Easier'|'Standard'|'Harder';type A={id:string;student:string;prompt:string;topic:string;given:string;answer:string;correct:boolean;when:string;difficulty:L;xp:number};const kids=['Malcolm N','Madison','Kyle','Kevin','Donnie','Aaliyah','Aiden','Amelia','Benjamin','Caleb','Camila','Carter','Charlotte','Chloe','Daniel','Ella','Ethan','Grace','Harper','Henry'];const colors=['#f97316','#14b8a6','#8b5cf6','#ec4899','#3b82f6'];
const xp=(l:L)=>l==='Harder'?20:l==='Easier'?8:10;const pct=(x:A[])=>x.length?Math.round(x.filter(a=>a.correct).length/x.length*100):0;function q(i:number,l:L){const p=parks[i%parks.length],f=figures[i%figures.length];if(i%3===0)return{prompt:`Which state is ${p.name} in?`,answer:p.state.split(' and ')[0],topic:'National Park Units',fact:p.fact};if(i%3===1)return{prompt:`Where was ${f.name} born?`,answer:f.state,topic:'Black History Geography',fact:f.fact};return{prompt:`Which state should you click to find ${p.name}?`,answer:p.state.split(' and ')[0],topic:'Map Mission',fact:p.fact}}
export default function Home(){const[student,setStudent]=useState(kids[0]),[level,setLevel]=useState<L>('Standard'),[round,setRound]=useState(0),[answer,setAnswer]=useState(''),[msg,setMsg]=useState(''),[tab,setTab]=useState<'Mission'|'Map Lab'|'Park Map'|'Park Atlas'|'Black History'>('Mission'),[attempts,setAttempts]=useState<A[]>([]),[settings,setSettings]=useState<Record<string,L>>({}),[login,setLogin]=useState(false),[teacher,setTeacher]=useState(false),[u,setU]=useState(''),[pw,setPw]=useState(''),[review,setReview]=useState(kids[0]);const mission=useMemo(()=>q(round,level),[round,level]),mine=attempts.filter(a=>a.student===student);useEffect(()=>{fetch(`/api/student?student=${encodeURIComponent(student)}`).then(r=>r.json()).then(x=>setLevel(x.difficulty||'Standard'))},[student]);useEffect(()=>{if(teacher)fetch('/api/classroom').then(r=>r.json()).then(x=>{setAttempts(x.attempts||[]);setSettings(x.settings||{})})},[teacher]);function save(prompt:string,answer:string,topic:string,chosen:string){const correct=chosen.trim().toLowerCase()===answer.toLowerCase(),row:A={id:crypto.randomUUID(),student,prompt,topic,given:chosen||'—',answer,correct,when:new Date().toISOString(),difficulty:level,xp:correct?xp(level):0};setAttempts(x=>[...x,row]);fetch('/api/classroom',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(row)});setMsg(correct?`Excellent! +${row.xp} XP${level==='Harder'?' for a harder mission!':''}`:`Not quite — ${answer} is the answer.`)}async function sign(e:React.FormEvent){e.preventDefault();const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:pw})});if(r.ok){setTeacher(true);setLogin(false)}else setMsg('Teacher sign-in did not match.')}async function assign(v:L){setSettings(x=>({...x,[review]:v}));await fetch('/api/classroom',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({student:review,difficulty:v})})}
if(teacher){const rows=attempts.filter(a=>a.student===review).slice().reverse(),assigned=settings[review]||'Standard';return <main><nav><div className="brand"><b>★ STATE SCOUT</b><small>Teacher Atlas</small></div><button className="return" onClick={()=>setTeacher(false)}>← Student view</button></nav><section className="teacher"><header><p>TEACHER MODE · US EXPLORER</p><h1>Guide every explorer<br/><em>across the map.</em></h1><div className="classscore"><b>{pct(attempts)}%</b><span>class accuracy<br/>{attempts.length} saved answers</span></div></header><div className="dashboard"><aside><p>STUDENT PROFILES · 20</p>{kids.map((n,i)=>{const data=attempts.filter(a=>a.student===n);return <button key={n} className={review===n?'chosen':''} onClick={()=>setReview(n)}><i style={{background:colors[i%5]}}>{n[0]}</i><span><b>{n}</b><small>{pct(data)}% · {settings[n]||'Standard'}</small></span></button>})}</aside><section className="report"><div className="name"><div><p>EXPLORER REPORT</p><h2>{review}</h2></div><b>{pct(rows)}%<small>accuracy</small></b></div><article className="assign"><p>QUEST DIFFICULTY</p><h3>Choose {review}&apos;s next quest level</h3><span>Harder missions earn <b>20 XP</b> when correct.</span><div>{(['Easier','Standard','Harder']as L[]).map(v=><button key={v} onClick={()=>assign(v)} className={assigned===v?v.toLowerCase():''}>{v==='Easier'?'↓ Easier':v==='Standard'?'◆ Standard':'↑ Harder'}<small>{v==='Harder'?'+20 XP credit':v==='Easier'?'Confidence builder':'Grade-level explorer work'}</small></button>)}</div></article><article className="insight"><b>Next focus</b><h3>{rows.some(a=>!a.correct)?'Review map locations':'Ready for deeper exploration!'}</h3><span>Current assignment: <strong>{assigned}</strong> missions</span></article><section className="history"><h3>Saved explorer history</h3>{rows.length?rows.map(a=><div className="row" key={a.id}><i className={a.correct?'yes':'no'}>{a.correct?'✓':'!'}</i><span><b>{a.topic} <mark>{a.difficulty}</mark></b><small>{a.prompt}</small></span><em>{a.given}<small>Correct: {a.answer} · +{a.xp} XP</small></em></div>):<p>No saved answers yet.</p>}</section></section></div></section></main>}
const total=mine.filter(a=>a.correct).reduce((n,a)=>n+a.xp,0);return <main><nav><div className="brand"><b>★ STATE SCOUT</b><small>US Geography Explorer</small></div><div className="nav"><button onClick={()=>setLogin(true)}>Teacher Mode</button><span>⚡ {mine.filter(a=>a.correct).length} streak</span><strong>✦ {total} XP</strong></div></nav><div className="tabs">{(['Mission','Map Lab','Park Map','Park Atlas','Black History']as const).map(x=><button className={tab===x?'on':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div><section className="shell"><aside className="roster"><p>EXPLORER CREW <b>20</b></p>{kids.map((n,i)=><button key={n} className={student===n?'active':''} onClick={()=>{setStudent(n);setRound(i);setAnswer('');setMsg('')}}><i style={{background:colors[i%5]}}>{n[0]}</i>{n}</button>)}</aside><section className="mission">{tab==='Mission'&&<><p>{level.toUpperCase()} EXPLORER MISSION</p><h1>Discover the United States,<br/><em>{student.split(' ')[0]}.</em></h1><label className={level.toLowerCase()}>{level==='Harder'?'↑ Harder mission · double XP':level==='Easier'?'↓ Easier mission':'◆ Standard mission'}</label><article><div><span>{mission.topic} · {level}</span><b>Mission 1 / 3</b></div><h2>{mission.prompt}</h2><input value={answer} onChange={e=>setAnswer(e.target.value)} onKeyDown={e=>e.key==='Enter'&&save(mission.prompt,mission.answer,mission.topic,answer)} placeholder="Type your answer"/><button onClick={()=>save(mission.prompt,mission.answer,mission.topic,answer)}>Check answer →</button>{msg&&<p className="feedback">{msg} <a onClick={()=>{setRound(x=>x+1);setAnswer('');setMsg('')}}>Next mission</a></p>}<small>💡 {mission.fact}</small></article><button className="park-link" onClick={()=>setTab('Park Map')}>🗺️ See Our National Parks →</button></>}{tab==='Park Map'&&<ParkMap/>}{tab==='Map Lab'&&<MapLab onAnswer={(state)=>save(`Click the state for ${mission.topic}`,mission.answer,'Interactive Map',state)} target={mission.answer}/>} {tab==='Park Atlas'&&<Atlas/>}{tab==='Black History'&&<History/>}</section><aside className="right"><div><p>YOUR ATLAS</p><h3>Current level</h3><b className="big">{level}</b><span>{level==='Harder'?'Correct answers earn 20 XP.':'Your teacher chose this mission level.'}</span></div><div><p>EXPLORE</p><b className="percent">{parks.length}+</b><span>park units and landmarks in the growing explorer library.</span></div><div className="tip">★ Map maker tip<br/><small>Click Map Lab to practice location skills.</small></div></aside></section>{login&&<div className="overlay"><form onSubmit={sign}><button type="button" onClick={()=>setLogin(false)}>×</button><p>TEACHER MODE</p><h2>Welcome, map guide.</h2><label>Username<input value={u} onChange={e=>setU(e.target.value)}/></label><label>Password<input type="password" value={pw} onChange={e=>setPw(e.target.value)}/></label><button>Enter Teacher Mode →</button></form></div>}</main>}
